{
  "name": "opencode-swarm-lite",
  "version": "2.0.0",
  "description": "Measured adaptive orchestration for OpenCode: a learned cost model and scheduler that choose serial, batched, small/full, speculative or pipeline execution; warm lane pool, versioned context capsules, convergence/dedup, adaptive verification, provider routing, telemetry and replay. ONE parent, lanes only when parallelism beats serial. No gates, no bureaucracy.",
  "type": "module",
  "author": "Arihant Bharanidhran <arihantbharani@outlook.com>",
  "license": "MIT",
  "copyright": "Copyright (c) 2026 Arihant Bharanidhran <arihantbharani@outlook.com>",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "swarm",
    "multi-agent",
    "orchestration",
    "subagents",
    "adaptive-scheduler",
    "cost-model",
    "warm-lanes",
    "context-capsules",
    "adaptive-verification",
    "deterministic-replay",
    "specialist-roles",
    "multimodal",
    "rate-limit",
    "auto-compaction"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Arihant-Bharanidharan/opencode-swarm-lite.git"
  },
  "bugs": {
    "url": "https://github.com/Arihant-Bharanidharan/opencode-swarm-lite/issues"
  },
  "homepage": "https://github.com/Arihant-Bharanidharan/opencode-swarm-lite#readme",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "index.ts",
    "src"
  ],
  "scripts": {
    "typecheck": "bunx --bun tsc --noEmit -p tsconfig.json",
    "test": "bun -e \"const g=new Bun.Glob('test/**/*.test.ts');const files=g.scanSync('.');let bad=0;for(const f of files){console.log('RUN '+f);const r=Bun.spawnSync([process.execPath,f],{stdout:'inherit',stderr:'inherit'});if(r.exitCode){bad=1}}if(files.length===0){console.log('no test files found')}process.exit(bad)\""
  },
  "dependencies": {
    "@opencode/plugin": "^2.1.2"
  },
  "devDependencies": {
    "@types/node": "^26.6.5",
    "typescript": "^7.0.2"
  }
}
